// minimal latency 4-sorter for B bits values
// generated by mlnsgenfastc
// comparisons=6, total cases=64, orderings=24
module nsorter_4 #(
  parameter B = 64
) (
  input [B-1:0] i0,
  output reg [B-1:0] o0,
  input [B-1:0] i1,
  output reg [B-1:0] o1,
  input [B-1:0] i2,
  output reg [B-1:0] o2,
  input [B-1:0] i3,
  output reg [B-1:0] o3
);
  wire c0 = i0 < i1;
  wire c1 = i0 < i2;
  wire c2 = i0 < i3;
  wire c3 = i1 < i2;
  wire c4 = i1 < i3;
  wire c5 = i2 < i3;
  always @(*) begin
    casez ({c0,c1,c2,c3,c4,c5})
      6'b1?1100,6'b1?1111,6'b?11011: o0=i0; // 6 cases, 3 merged cases
      6'b0?0110,6'b0?1111,6'b?01111: o0=i1; // 6 cases, 3 merged cases
      6'b?00001,6'b?01011: o0=i2; // 6 cases, 2 merged cases
      6'b?00000,6'b??0100: o0=i3; // 6 cases, 2 merged cases
      default: o0={B{1'bx}}; // 40 unreachable cases
    endcase
  end
  always @(*) begin
    casez ({c0,c1,c2,c3,c4,c5})
      6'b0?1111,6'b1?0100,6'b?01011: o1=i0; // 6 cases, 3 merged cases
      6'b0?0100,6'b1?1111,6'b?01011: o1=i1; // 6 cases, 3 merged cases
      6'b?00000,6'b?01111,6'b?11011: o1=i2; // 6 cases, 3 merged cases
      6'b0?0110,6'b1?1100,6'b?00001: o1=i3; // 6 cases, 3 merged cases
      default: o1={B{1'bx}}; // 40 unreachable cases
    endcase
  end
  always @(*) begin
    casez ({c0,c1,c2,c3,c4,c5})
      6'b0?1111,6'b1?0001,6'b?10110: o2=i0; // 6 cases, 3 merged cases
      6'b0?0001,6'b1?1011,6'b?11100: o2=i1; // 6 cases, 3 merged cases
      6'b?00110,6'b?11000,6'b?11111: o2=i2; // 6 cases, 3 merged cases
      6'b0?0111,6'b1?1001,6'b?11110: o2=i3; // 6 cases, 3 merged cases
      default: o2={B{1'bx}}; // 40 unreachable cases
    endcase
  end
  always @(*) begin
    casez ({c0,c1,c2,c3,c4,c5})
      6'b0?0100,6'b0?0111,6'b?00011: o3=i0; // 6 cases, 3 merged cases
      6'b1?0000,6'b1?1001,6'b?01001: o3=i1; // 6 cases, 3 merged cases
      6'b?10100,6'b?11110: o3=i2; // 6 cases, 2 merged cases
      6'b?01011,6'b??1111: o3=i3; // 6 cases, 2 merged cases
      default: o3={B{1'bx}}; // 40 unreachable cases
    endcase
  end
endmodule
